var a=`1390-australian-meat-pie`;var i=`world-1390`;var n=`AU`;var s=`oceania`;var o=8;var r=96;var u={en:`Australian Meat Pie`,ua:`Австралійський м'ясний пиріг`};var l={en:`Australian Meat Pie is a dish from Australia featuring all-purpose flour, ground beef, yellow onion, garlic. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Австралійський м'ясний пиріг, страва кухні країни Австралія з такими основними складниками: пшеничне борошно універсальне, яловичий фарш, жовта цибуля, часник. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var d=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 18 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 18 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:18,i:[[`all-purpose-flour`,500,`g`],[`unsalted-butter`,190,`g`],[`water`,190,`ml`],[`table-salt`,9,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 13 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 13 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:13,i:[[`ground-beef`,630,`g`],[`yellow-onion`,180,`g`],[`garlic`,4,`clove`],[`canola-oil`,35,`ml`]]},{en:`Cook the listed sauce ingredients over medium-low heat for about 12 minutes until aromatic and slightly thickened.`,ua:`Готуйте складники соусу на помірно слабкому вогні приблизно 12 хвилин до появи аромату та легкого загустіння.`,t:[`sauteing`,`reducing-sauce`],m:12,i:[[`beef-stock`,300,`ml`],[`all-purpose-flour`,50,`g`],[`tomato-paste`,40,`g`],[`worcestershire-sauce`,25,`ml`]]},{en:`Enclose cooled thick beef gravy in raw pastry with a tight crimp and steam vents. Bake at 200°C until the pastry is deeply golden and filling very hot.`,ua:`Загорніть охолоджену густу м’ясну начинку в сире тісто, щільно защипніть і зробіть отвори для пари. Печіть при 200°C до темно-золотистої скоринки та гарячої середини.`,t:[`stuffing-vegetables`],m:15,i:[]},{en:`Bake the shaped or assembled mixture in a preheated oven for about 38 minutes until set and cooked through.`,ua:`Випікайте сформовану або складену масу в розігрітій духовці приблизно 38 хвилин до готовності.`,t:[`baking`],m:38,i:[]}];var g={slug:a,id:i,country:`AU`,region:s,servings:8,minutes:96,title:u,text:l,steps:d};export{n as country,g as default,i as id,r as minutes,s as region,o as servings,a as slug,d as steps,l as text,u as title};